<?php
namespace App\Http\Controllers;
use App\Http\Requests\StoreSubscriptionRequest; use App\Models\Client; use App\Models\Invoice; use App\Models\ServicePackage; use App\Models\Subscription; use Carbon\Carbon; use Illuminate\Support\Facades\DB;
class SubscriptionController extends Controller
{
    public function index(){$subscriptions=Subscription::with(['client','servicePackage'])->latest('end_date')->paginate(15);return view('subscriptions.index',compact('subscriptions'));}
    public function create(){return view('subscriptions.form',['subscription'=>new Subscription(['start_date'=>now()->toDateString(),'status'=>'active']),'clients'=>Client::orderBy('name')->get(),'packages'=>ServicePackage::where('is_active',true)->orderBy('name')->get()]);}
    public function store(StoreSubscriptionRequest $request){$data=$request->validated();$data['end_date']=$data['end_date']??Carbon::parse($data['start_date'])->addYear()->subDay()->toDateString();Subscription::create($data);return redirect()->route('subscriptions.index')->with('success','Langganan berhasil ditambahkan.');}
    public function edit(Subscription $subscription){return view('subscriptions.form',['subscription'=>$subscription,'clients'=>Client::orderBy('name')->get(),'packages'=>ServicePackage::where('is_active',true)->orderBy('name')->get()]);}
    public function update(StoreSubscriptionRequest $request,Subscription $subscription){$data=$request->validated();$data['end_date']=$data['end_date']??Carbon::parse($data['start_date'])->addYear()->subDay()->toDateString();$subscription->update($data);return back()->with('success','Langganan berhasil diperbarui.');}
    public function renew(Subscription $subscription){abort_if($subscription->status==='frozen',403,'Langganan dibekukan tidak dapat diperpanjang.');$package=$subscription->servicePackage;$new=DB::transaction(function()use($subscription,$package){$new=Subscription::create(['client_id'=>$subscription->client_id,'service_package_id'=>$subscription->service_package_id,'previous_subscription_id'=>$subscription->id,'start_date'=>$subscription->renewalStartDate(),'end_date'=>$subscription->renewalStartDate()->copy()->addYear()->subDay(),'contract_value'=>$package->default_price,'status'=>'active']);$subscription->update(['status'=>'renewed']);$number='INV/'.now()->format('Y/m/').str_pad((string)(Invoice::where('number','like','INV/'.now()->format('Y/m/').'%')->count()+1),4,'0',STR_PAD_LEFT);Invoice::create(['number'=>$number,'source'=>'generated','subscription_id'=>$new->id,'issued_at'=>now()->toDateString(),'due_date'=>now()->addDays((int)setting('invoice_due_days',14))->toDateString(),'subtotal'=>$new->contract_value,'tax_amount'=>0,'total'=>$new->contract_value,'status'=>'unpaid']);return $new;});return redirect()->route('subscriptions.index')->with('success','Langganan berhasil diperpanjang dan tagihan dibuat.');}
    public function freeze(Subscription $subscription){$subscription->update(['status'=>'frozen','freeze_reason'=>request('freeze_reason')]);return back()->with('success','Langganan berhasil dibekukan.');}
}
